import { ProductExample } from '@/react/components/site/ProductExample'
// A media search request in three tabs beside its response and the creatives it returned (Acme).

const tabs = [
  {
    "id": "mcp",
    "label": "MCP",
    "language": "bash",
    "code": "# Ask your agent
Find running shoe ads that ran for more than 30 days.

# It calls searchMedia
searchMedia({
  "query": "running shoe ads",
  "minDaysLive": 30,
  "limit": 3
})"
  },
  {
    "id": "rest",
    "label": "REST",
    "language": "bash",
    "code": "curl -X POST https://api.acme.com/v1/media \
  -H "Authorization: Bearer $ACME_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "query": "running shoe ads",
    "minDaysLive": 30,
    "limit": 3
  }'"
  },
  {
    "id": "python",
    "label": "Python",
    "language": "python",
    "code": "import os
from acme import Acme

client = Acme(token=os.environ["ACME_API_KEY"])

result = client.search_media(
    query="running shoe ads",
    min_days_live=30,
    limit=3,
)"
  }
]

const response = "{
  "count": 3,
  "media": [
    {
      "id": "1001",
      "brand": "Acme Run",
      "platform": "Instagram",
      "daysLive": 74
    },
    {
      "id": "1002",
      "brand": "Acme Trail",
      "platform": "TikTok",
      "daysLive": 61
    },
    {
      "id": "1003",
      "brand": "Acme Fit",
      "platform": "Meta",
      "daysLive": 48
    }
  ]
}"

export default function Media() {
  return (
    <ProductExample
      id="media-search"
      question="Find running shoe ads that ran for more than 30 days."
      tabs={tabs}
      response={response}
      specs={[{"label": "Endpoint", "value": "POST /media"}, {"label": "MCP tool", "value": "searchMedia"}, {"label": "Rate limit", "value": "120 requests a minute"}]}
      media={{"label": "Returned creatives", "items": [{"brand": "Acme Run", "tone": 3, "caption": "Built for miles.", "meta": "Acme Run, 74 days live"}, {"brand": "Acme Trail", "tone": 2, "caption": "Off the road.", "meta": "Acme Trail, 61 days live"}, {"brand": "Acme Fit", "tone": 4, "caption": "First 5K.", "meta": "Acme Fit, 48 days live"}]}}
    />
  )
}

